const readline = require("readline-sync");

console.log("Jogo de adivinhação, chute um numero entre 1 e 10: ");

const numSek = Math.floor(Math.random()*10 + 1);

let chute = readline.questionInt("Qual é o seu palpite?: ");
let tentativas = 1;

while(chute != numSek){
    if (chute <= numSek){
        console.log("O numero secreto é Maior.");
    }

    else{
        console.log("O numero é menor.");
    }

    chute = readline.questionInt("tente de novo.");
    tentativas++;
}
console.log(`parabens você asertou, o numero era ${numSek}, em ${tentativas} chutes, agora cai fora daqui seu miseravel`);